from collections import deque,Counter
R,C=len(grid),len(grid[0])
def comps(color):
 seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c]!=color or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]==color and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   rs=[x for x,y in cells]; cs=[y for x,y in cells]
   out.append((min(rs),max(rs),min(cs),max(cs),len(cells)))
 return out
for color in (8,4): print(color,comps(color))

out=[[9]*C for _ in range(R)]
for color in (8,4):
 for r0,r1,c0,c1,_ in comps(color):
  for r in range(r0,r1+1):
   for c in range(c0,c1+1): out[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in out))
